<section class="components-page form-elements-page">
  <div class="row g-4">
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Basic Switches</h5></div><div class="card-body form-stack"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="switchDefault"><label class="form-check-label" for="switchDefault">Default switch checkbox input</label></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="switchChecked" checked><label class="form-check-label" for="switchChecked">Checked switch checkbox input</label></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="switchDisabled" disabled><label class="form-check-label" for="switchDisabled">Disabled switch checkbox input</label></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="switchCheckedDisabled" checked disabled><label class="form-check-label" for="switchCheckedDisabled">Disabled checked switch checkbox input</label></div></div></div></div>
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Switch Colors</h5></div><div class="card-body form-stack"><div class="form-check form-switch switch-primary"><input class="form-check-input" type="checkbox" id="switchPrimary" checked><label class="form-check-label" for="switchPrimary">Primary</label></div><div class="form-check form-switch switch-success"><input class="form-check-input" type="checkbox" id="switchSuccess" checked><label class="form-check-label" for="switchSuccess">Success</label></div><div class="form-check form-switch switch-warning"><input class="form-check-input" type="checkbox" id="switchWarning" checked><label class="form-check-label" for="switchWarning">Warning</label></div><div class="form-check form-switch switch-danger"><input class="form-check-input" type="checkbox" id="switchDanger" checked><label class="form-check-label" for="switchDanger">Danger</label></div></div></div></div>
  </div>
  <div class="row g-4"><div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Switch Sizes</h5></div><div class="card-body form-stack"><div class="form-check form-switch switch-lg"><input class="form-check-input" type="checkbox" id="switchLarge" checked><label class="form-check-label" for="switchLarge">Large switch</label></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="switchRegular" checked><label class="form-check-label" for="switchRegular">Default switch</label></div><div class="form-check form-switch switch-sm"><input class="form-check-input" type="checkbox" id="switchSmall" checked><label class="form-check-label" for="switchSmall">Small switch</label></div></div></div></div><div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Switch With Icons</h5></div><div class="card-body form-stack"><div class="form-check form-switch switch-icon"><input class="form-check-input" type="checkbox" id="switchIconWifi" checked><label class="form-check-label" for="switchIconWifi"><i class="bi bi-wifi me-1"></i>Wi-Fi</label></div><div class="form-check form-switch switch-icon"><input class="form-check-input" type="checkbox" id="switchIconMoon"><label class="form-check-label" for="switchIconMoon"><i class="bi bi-moon me-1"></i>Quiet mode</label></div></div></div></div></div>
</section>